#define main legacy_main
#include "bgmv-cuda/main.cu"
#undef main
#include <functional>
const int TT=4,HH=72,RR=16,LL=3;
struct Case{int mode,bs;std::function<void()>run;std::vector<float>want;};
template<int BS>void addcases(std::vector<Case>&cases,float*Y,__half*Z,__half*A,__half*W,float*X,__half*V,int*I){for(int mode=1;mode<=4;mode++){Case c;c.mode=mode;c.bs=BS;c.run=[=](){if(mode<=2)launch_bgmv_shrink<BS>(Y,A,W,I,TT,HH,RR,.5f,mode==2);else launch_bgmv_expand<BS>(Z,X,V,I,TT,HH,RR,mode==4);};for(int t=0;t<TT;t++)for(int ch=0;ch<(mode<=2?RR:HH);ch++){int lid=2*t%LL,n=0;if(mode<=2)for(int k=0;k<HH;k++)n+=((t*HH+k)%17-8)*(((lid*RR+ch)*HH+k)%13-6);else for(int k=0;k<RR;k++)n+=((t*RR+k)%11-5)*(((lid*HH+ch)*RR+k)%7-3);float dot=float(n)/1024.f,value=0;for(int rep=0;rep<10;rep++)value=mode<=2?value+.5f*dot:__half2float(__float2half((mode==4?value:0.f)+dot));c.want.push_back(value);}cases.push_back(c);}}
int main(){std::vector<__half>a(TT*HH),w(LL*RR*HH),v(LL*HH*RR);std::vector<float>x(TT*RR);int ids[TT];for(int i=0;i<TT;i++)ids[i]=2*i%LL;for(size_t i=0;i<a.size();i++)a[i]=__float2half(float(int(i%17)-8)/32);for(size_t i=0;i<w.size();i++)w[i]=__float2half(float(int(i%13)-6)/32);for(size_t i=0;i<v.size();i++)v[i]=__float2half(float(int(i%7)-3)/32);for(size_t i=0;i<x.size();i++)x[i]=float(int(i%11)-5)/32;__half*A,*W,*V,*Z;float*X,*Y;int*I;GPU_CHECK(cudaMalloc(&A,a.size()*2));GPU_CHECK(cudaMalloc(&W,w.size()*2));GPU_CHECK(cudaMalloc(&V,v.size()*2));GPU_CHECK(cudaMalloc(&X,x.size()*4));GPU_CHECK(cudaMalloc(&Y,TT*RR*4));GPU_CHECK(cudaMalloc(&Z,TT*HH*2));GPU_CHECK(cudaMalloc(&I,TT*4));GPU_CHECK(cudaMemcpy(A,a.data(),a.size()*2,cudaMemcpyHostToDevice));GPU_CHECK(cudaMemcpy(W,w.data(),w.size()*2,cudaMemcpyHostToDevice));GPU_CHECK(cudaMemcpy(V,v.data(),v.size()*2,cudaMemcpyHostToDevice));GPU_CHECK(cudaMemcpy(X,x.data(),x.size()*4,cudaMemcpyHostToDevice));GPU_CHECK(cudaMemcpy(I,ids,TT*4,cudaMemcpyHostToDevice));std::vector<Case>cases;addcases<32>(cases,Y,Z,A,W,X,V,I);addcases<64>(cases,Y,Z,A,W,X,V,I);addcases<128>(cases,Y,Z,A,W,X,V,I);addcases<256>(cases,Y,Z,A,W,X,V,I);addcases<512>(cases,Y,Z,A,W,X,V,I);addcases<1024>(cases,Y,Z,A,W,X,V,I);for(auto&c:cases){GPU_CHECK(cudaMemset(c.mode<=2?(void*)Y:(void*)Z,0,c.want.size()*(c.mode<=2?4:2)));c.run();}GPU_CHECK(cudaDeviceSynchronize());for(int trial=1;trial<=5;trial++){double total=0,err=0;bool ok=true;std::vector<float>got;for(auto&c:cases){GPU_CHECK(cudaMemset(c.mode<=2?(void*)Y:(void*)Z,0,c.want.size()*(c.mode<=2?4:2)));GPU_CHECK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int k=0;k<10;k++)c.run();GPU_CHECK(cudaDeviceSynchronize());total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/10;std::vector<float>out(c.want.size());if(c.mode<=2)GPU_CHECK(cudaMemcpy(out.data(),Y,out.size()*4,cudaMemcpyDeviceToHost));else{std::vector<__half>half(out.size());GPU_CHECK(cudaMemcpy(half.data(),Z,half.size()*2,cudaMemcpyDeviceToHost));for(size_t i=0;i<out.size();i++)out[i]=__half2float(half[i]);}for(size_t i=0;i<out.size();i++){err=std::max(err,double(fabs(out[i]-c.want[i])));ok=ok&&std::isfinite(out[i])&&fabs(out[i]-c.want[i])<.1f;}got.insert(got.end(),out.begin(),out.end());}char path[64];snprintf(path,64,"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(got.data(),4,got.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.15g,\"correct\":%s,\"checked_values\":4224,\"max_abs_error\":%.15g,\"timing_region\":\"sum_six_blocks_four_modes_kernel_means\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":4224,\"byte_order\":\"little\"}}\n",trial,total,ok?"true":"false",err,path);if(!ok)return 1;}cudaFree(A);cudaFree(W);cudaFree(V);cudaFree(X);cudaFree(Y);cudaFree(Z);cudaFree(I);}
